CREATE TABLE IF NOT EXISTS telegram_binding(id INTEGER PRIMARY KEY CHECK(id=1),bot INTEGER NOT NULL,agent TEXT NOT NULL,offset INTEGER NOT NULL DEFAULT 0) STRICT;
    CREATE TABLE IF NOT EXISTS telegram_inbox(update_id INTEGER PRIMARY KEY,chat INTEGER NOT NULL,message INTEGER NOT NULL,text TEXT NOT NULL,thread TEXT NOT NULL,turn TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'queued',UNIQUE(chat,message)) STRICT;
    CREATE TABLE IF NOT EXISTS telegram_media(turn TEXT PRIMARY KEY,remote TEXT NOT NULL,name TEXT NOT NULL,size INTEGER,upload TEXT NOT NULL UNIQUE,bytes BLOB) STRICT;
    CREATE TABLE IF NOT EXISTS telegram_document_workflows(id TEXT PRIMARY KEY,run TEXT NOT NULL) STRICT;
    CREATE TABLE IF NOT EXISTS telegram_documents(id TEXT PRIMARY KEY,turn TEXT NOT NULL,thread TEXT NOT NULL,file TEXT NOT NULL,name TEXT NOT NULL,bytes BLOB NOT NULL,UNIQUE(turn,file)) STRICT;
    CREATE TABLE IF NOT EXISTS telegram_workflows(run TEXT PRIMARY KEY,chat INTEGER NOT NULL,workflow TEXT NOT NULL,version INTEGER NOT NULL) STRICT;
    CREATE TABLE IF NOT EXISTS telegram_approvals(run TEXT NOT NULL,revision INTEGER NOT NULL,notice TEXT NOT NULL UNIQUE,PRIMARY KEY(run,revision)) STRICT;
    CREATE TABLE IF NOT EXISTS telegram_callbacks(notice TEXT PRIMARY KEY,id TEXT NOT NULL UNIQUE,chat INTEGER NOT NULL,message INTEGER NOT NULL,selection INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'queued') STRICT;
    CREATE TABLE IF NOT EXISTS telegram_workflow_cancels(id TEXT PRIMARY KEY,run TEXT NOT NULL,revision INTEGER NOT NULL) STRICT;
    CREATE TABLE IF NOT EXISTS telegram_questions(id TEXT PRIMARY KEY,turn TEXT NOT NULL,thread TEXT NOT NULL,chat INTEGER NOT NULL) STRICT;
    CREATE TABLE IF NOT EXISTS telegram_closed_threads(id TEXT PRIMARY KEY) STRICT;
    CREATE TABLE IF NOT EXISTS telegram_outbox(id TEXT PRIMARY KEY,chat INTEGER NOT NULL,reply_to INTEGER NOT NULL,text TEXT NOT NULL,status TEXT NOT NULL,part INTEGER NOT NULL DEFAULT 0,message_ids TEXT NOT NULL DEFAULT '[]',error TEXT) STRICT;
    CREATE TABLE IF NOT EXISTS telegram_recoveries(reply TEXT NOT NULL,revision INTEGER NOT NULL,action TEXT NOT NULL,status TEXT NOT NULL,part INTEGER NOT NULL,error TEXT,created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(reply,revision)) STRICT;
    UPDATE telegram_outbox SET status='uncertain',error='Interrupted Telegram send; inspect delivery before sending again.' WHERE status='sending';
